DROP TABLE IF EXISTS `collys`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `collys` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` char(128) COLLATE utf8_unicode_ci DEFAULT NULL,
  `artists` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `artist_ids` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `crews` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `crew_ids` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `year` int(11) DEFAULT NULL,
  `type` char(11) COLLATE utf8_unicode_ci DEFAULT NULL,
  `filename` char(60) COLLATE utf8_unicode_ci NOT NULL DEFAULT '',
  `timestamp` int(11) DEFAULT NULL,
  `rating` float DEFAULT NULL,
  `uploader` char(32) COLLATE utf8_unicode_ci DEFAULT NULL,
  `uploader_id` int(10) unsigned DEFAULT NULL,
  `filesize` int(16) DEFAULT NULL,
  `month` int(2) DEFAULT NULL,
  `file_id` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `view_counter` int(11) DEFAULT NULL,
  `downloads` int(11) DEFAULT NULL,
  `day` int(2) DEFAULT NULL,
  `broken` int(1) DEFAULT NULL,
  `broken_comment` text COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `filename` (`filename`) USING BTREE,
  KEY `uploader_id` (`uploader_id`),
  FULLTEXT KEY `name` (`name`,`artists`,`crews`,`filename`)
) ENGINE=InnoDB AUTO_INCREMENT=3852 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

