DROP TABLE IF EXISTS `wallposts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallposts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `wall_id` int(10) unsigned DEFAULT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
  `tag` varchar(255) NOT NULL,
  `nick` varchar(255) NOT NULL,
  `created` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `wall_id` (`wall_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `wallposts_ibfk_1` FOREIGN KEY (`wall_id`) REFERENCES `walls` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `wallposts_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8;
